using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Geometry.AlgebraicBoundary;

internal sealed class BoundaryEliminationDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Boundary projection and arbitrary-degree factor divisibility.",
        H("Boundary projection and arbitrary-degree factor divisibility."),
        Blocks(
            Paragraph(Text("Let C be a closed convex cone in a real normed carrier, e an actual interior direction and z an actual point of its entire ambient boundary. Every neighborhood N of z admits a neighborhood of zero such that every displaced line z+v+te meets the entire boundary inside N. Choose a short interval along e whose lower endpoint is outside C and whose upper endpoint is interior. Both properties persist for small v. The connected line segment must cross the boundary, and a product neighborhood keeps the entire segment in N. No smoothness, boundary parametrization, semialgebraicity or polynomial degree bound enters this construction.")),
            Paragraph(Text("Suppose f times g and h vanish on the entire boundary, with g continuous and g(z) nonzero. Let pi be a continuous linear transverse projection with pi(e)=0 and with a continuous linear section J. An identity A f+B h=R composed with pi, where R is a transverse multivariate polynomial, forces R to be zero. The boundary projection constructs a common zero of f and h over each transverse point in a neighborhood of pi(z); the nonvanishing of g holds throughout the chosen boundary neighborhood. Polynomial function extensionality on a box with infinite sides then gives the polynomial identity R=0.")),
            Paragraph(Text("For actual polynomial coordinates (u,pi), let P and Q be polynomials in u with coefficients in the real transverse polynomial ring. If P is irreducible and has positive degree in u, P times a continuous residual factor vanishes on the entire boundary, that factor is nonzero at z, and Q vanishes on the entire boundary, then P divides Q. The pinned Mathlib resultant Bezout identity supplies the transverse eliminant. The geometric bridge makes this resultant zero. Irreducibility and positive u-degree imply primitivity; Gauss's lemma transfers irreducibility to the fraction field, the zero resultant forces noncoprimality there, and Gauss descent yields divisibility in the original polynomial ring. Q has arbitrary finite degree and need not be homogeneous.")),
            Paragraph(Text("BoundaryCoordinates constructs the invertible polynomial coordinate substitution on the original carrier. BoundaryPrincipalIdeal transports each irreducible factor and each arbitrary comparison equation through this equivalence and certifies positive univariate degree using an actual interior direction where the homogeneous minimum is nonzero. Minimum total degree supplies a boundary point where the complementary factor is nonzero; squarefreeness then combines all factor divisibilities. ConeMinimumBranch consumes that entire-boundary ideal theorem for the same selected positively oriented minimum used in its roots and closed-branch conclusions.")))));
}
